! Typed-handle wrappers, included into the module contains section.

    function hipsparseCreate_typed(handle) result(Create)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(hipsparseHandle_t) :: handle
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: Create
      Create = hipsparseCreate_(handle%ptr)
    end function hipsparseCreate_typed

    function hipsparseDestroy_typed(handle) result(Destroy)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(hipsparseHandle_t), value :: handle
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: Destroy
      Destroy = hipsparseDestroy_(handle%ptr)
    end function hipsparseDestroy_typed

