    function hipsparseGetGitRevision_typed(handle, rev) result(GetGitRevision)
      use, intrinsic :: iso_c_binding
      use hipfort_handles
      implicit none
      type(hipsparseHandle_t), value :: handle
      type(c_ptr), value :: rev
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: GetGitRevision
      GetGitRevision = hipsparseGetGitRevision_(handle%ptr, rev)
    end function hipsparseGetGitRevision_typed

    function hipsparseGetGitRevision_cstr(handle, rev) result(GetGitRevision)
      use, intrinsic :: iso_c_binding
      implicit none
      type(c_ptr), value :: handle
      character(len=*), intent(out) :: rev
      integer(kind(HIPSPARSE_STATUS_SUCCESS)) :: GetGitRevision
      character(len=len(rev)+1, kind=c_char), target :: rev__c
      integer :: i__c
      rev__c = repeat(c_null_char, len(rev)+1)
      GetGitRevision = hipsparseGetGitRevision_(handle, c_loc(rev__c))
      rev = ""
      do i__c = 1, len(rev)
        if (rev__c(i__c:i__c) == c_null_char) exit
        rev(i__c:i__c) = rev__c(i__c:i__c)
      end do
    end function hipsparseGetGitRevision_cstr

