      real(c_float),target,contiguous,dimension(..) :: y
      integer(kind(HIPSPARSE_INDEX_BASE_ZERO)) :: idxBase
      !
      hipsparseSaxpyi_assumed_rank = hipsparseSaxpyi_(handle%ptr,nnz,alpha,c_loc(xVal), &
        c_loc(xInd),c_loc(y),idxBase)
